{
  "task": "format_questions_to_latex",
  "questions": [
    {
      "source_id": "1",
      "stem": "A tracking station is located at the origin. A weather balloon is observed at position \\(\\vec r = 8\\hat{\\imath}+15\\hat{\\jmath}\\), where distances are measured in kilometers. Which statement is correct?",
      "options": [
        {
          "key": "A",
          "text": "The distance between the balloon and the station is 23 km.",
          "is_correct": false,
          "explanation": "This adds components (\\(8+15\\)) as if distance in 2D were the Manhattan distance, instead of using \\(\\sqrt{x^2+y^2}\\)."
        },
        {
          "key": "B",
          "text": "The distance between the balloon and the station is 17 km.",
          "is_correct": true,
          "explanation": "The distance from the origin to \\((x,y)\\) is the magnitude of the position vector: \\(r=\\|\\vec r\\|=\\sqrt{x^2+y^2}\\). Here \\(r=\\sqrt{8^2+15^2}=\\sqrt{64+225}=\\sqrt{289}=17\\,\\text{km}\\)."
        },
        {
          "key": "C",
          "text": "The distance between the balloon and the station is 15 km.",
          "is_correct": false,
          "explanation": "This confuses the \\(y\\)-component (15 km) with the total distance from the origin."
        },
        {
          "key": "D",
          "text": "The distance between the balloon and the station is 8 km.",
          "is_correct": false,
          "explanation": "This confuses the \\(x\\)-component (8 km) with the total distance from the origin."
        }
      ]
    },
    {
      "source_id": "2",
      "stem": "If the displacement of an object along the \\(x\\)-axis is given by \\(\\vec s(t)=\\big((0.60\\,\\text{m/s}^3)t^3+(5.5\\,\\text{m/s}^2)t^2\\big)\\hat{\\imath}\\), which statement is correct?",
      "options": [
        {
          "key": "A",
          "text": "This is a constant-acceleration motion.",
          "is_correct": false,
          "explanation": "Because \\(s(t)\\) contains a \\(t^3\\) term, differentiating twice gives an acceleration that depends on \\(t\\), so it is not constant."
        },
        {
          "key": "B",
          "text": "The magnitude of the acceleration is \\(5.5\\,\\text{m/s}^2\\).",
          "is_correct": false,
          "explanation": "\\(5.5\\,\\text{m/s}^2\\) is a coefficient in the displacement function, not the acceleration itself; you must differentiate twice to find \\(a(t)\\)."
        },
        {
          "key": "C",
          "text": "The magnitude of the acceleration at \\(t=0\\) is \\(0\\,\\text{m/s}^2\\).",
          "is_correct": false,
          "explanation": "Differentiating twice leaves a nonzero constant term in \\(a(t)\\), so \\(a(0)\\neq 0\\)."
        },
        {
          "key": "D",
          "text": "The magnitude of the acceleration at \\(t=0\\) is \\(11.0\\,\\text{m/s}^2\\).",
          "is_correct": true,
          "explanation": "Differentiate: \\(\\vec v(t)=\\frac{d\\vec s}{dt}=(3\\cdot 0.60\\,t^2+2\\cdot 5.5\\,t)\\hat{\\imath}=(1.8t^2+11t)\\hat{\\imath}\\). Then \\(\\vec a(t)=\\frac{d\\vec v}{dt}=(3.6t+11)\\hat{\\imath}\\), so at \\(t=0\\), \\(|\\vec a(0)|=11.0\\,\\text{m/s}^2\\)."
        }
      ]
    },
    {
      "source_id": "3",
      "stem": "An object takes 4.0 s to move from position A \\(\\big(\\vec r_A=-3.0\\hat{\\imath}-8.0\\hat{\\jmath}\\big)\\) to position B \\(\\big(\\vec r_B=9.0\\hat{\\imath}+5.0\\hat{\\jmath}\\big)\\), where length units are in meters. Which statement is correct?",
      "options": [
        {
          "key": "A",
          "text": "The straight-line distance between A and B is about 17.7 m.",
          "is_correct": true,
          "explanation": "The displacement is \\(\\Delta\\vec r=\\vec r_B-\\vec r_A=(9-(-3))\\hat{\\imath}+(5-(-8))\\hat{\\jmath}=12\\hat{\\imath}+13\\hat{\\jmath}\\). Its magnitude is \\(|\\Delta\\vec r|=\\sqrt{12^2+13^2}=\\sqrt{313}\\approx 17.69\\,\\text{m}\\approx 17.7\\,\\text{m}\\)."
        },
        {
          "key": "B",
          "text": "The speed at \\(t=0\\) must be \\(4.4\\,\\text{m/s}\\).",
          "is_correct": false,
          "explanation": "Dividing displacement magnitude by time gives an average speed (and even that assumes straight-line motion), but the initial speed is not determined by endpoints and total time alone."
        },
        {
          "key": "C",
          "text": "The acceleration at \\(t=0\\) must be \\(2.2\\,\\text{m/s}^2\\).",
          "is_correct": false,
          "explanation": "You cannot determine acceleration (or its value at \\(t=0\\)) uniquely from only initial/final positions and elapsed time without additional constraints (e.g., constant acceleration plus velocity information)."
        },
        {
          "key": "D",
          "text": "None of the above is correct.",
          "is_correct": false,
          "explanation": "Option A is correct because the straight-line separation is the magnitude of \\(\\Delta\\vec r\\), which is \\(\\sqrt{313}\\approx 17.7\\,\\text{m}\\)."
        }
      ]
    }
  ],
  "requirements": {
    "include_document_preamble": true,
    "include_macros": [
      "\\QBlock",
      "\\Correct",
      "\\Wrong"
    ],
    "format_all_questions_with_macros": true,
    "proper_math_formatting": true,
    "filename": "isomorphic_questions.tex"
  }
}

